      vi.useRealTimers();
    }
  });

  it("idleTimeout keeps hard expiration for header-carried sessions", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
