    }
  });

  it("does not resurrect a cleared session on an error response", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      let idCtr = 0;
      const config: SessionConfig = {
        name: "h3-clear-err",
        password: sessionConfig.password,
        idleTimeout: 60,
        generateId: () => `clr-${++idCtr}`,
      };
      t.app.get("/clear-err", async (event) => {
        await useSession(event, config);
        await clearSession(event, config);
        throw new HTTPError({ status: 403 });
      });
      t.app.get("/clear-err-ok", async (event) => {
        const session = await useSession(event, config);
        return { id: session.id };
      });

      const res1 = await t.fetch("/clear-err-ok");
      const cookie = res1.headers.getSetCookie().find((c) => c.startsWith("h3-clear-err="))!;

      // t=45s: past the reseal threshold, so `getSession` slides the window — and
      // that reseal must not outlive the clear
      vi.setSystemTime(t0 + 45_000);
      const res2 = await t.fetch("/clear-err", { headers: { Cookie: cookie } });
      expect(res2.status).toBe(403);
      const cleared = res2.headers.getSetCookie().filter((c) => c.startsWith("h3-clear-err="));
      expect(cleared).toHaveLength(1);
      expect(cleared[0]).toContain("Max-Age=0");
    } finally {
      vi.useRealTimers();
    }
  });

  it("applies every chunk of a chunked session cookie to error responses", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      const config: SessionConfig = {
        name: "h3-chunk-err",
        password: sessionConfig.password,
        idleTimeout: 60,
      };
      const big = "x".repeat(5000);
      t.app.get("/chunk-err-ok", async (event) => {
        const session = await useSession(event, config);
        await session.update({ big });
        return "ok";
      });
      t.app.get("/chunk-err", async (event) => {
        await useSession(event, config);
        throw new HTTPError({ status: 418 });
      });

      const res1 = await t.fetch("/chunk-err-ok");
      const setCookies = res1.headers.getSetCookie();
      expect(setCookies.length).toBeGreaterThan(1);
      const cookieHeader = setCookies.map((c) => c.split(";")[0]).join("; ");

      // t=45s: past the reseal threshold, so the errored request reseals
      vi.setSystemTime(t0 + 45_000);
      const res2 = await t.fetch("/chunk-err", { headers: { Cookie: cookieHeader } });
      expect(res2.status).toBe(418);
      expect(
        res2.headers
          .getSetCookie()
          .map((c) => c.split("=")[0])
          .sort(),
      ).toEqual(setCookies.map((c) => c.split("=")[0]).sort());
    } finally {
      vi.useRealTimers();
    }
  });

  it("stores large data in chunks", async () => {
    const token = Array.from({ length: 5000 /* ~4k + one more */ }).fill("x").join("");
    const res = await t.fetch("/", {
      method: "POST",
      headers: { Cookie: cookie },
      body: JSON.stringify({ token }),
    });

    const cookies = res.headers.getSetCookie();
    const cookieNames = cookies.map((c) => c.split("=")[0]);
    expect(cookieNames.length).toBe(3 /* head + 2 */);
    expect(cookieNames).toMatchObject(["h3-test", "h3-test.1", "h3-test.2"]);

    const body = await res.json();
    expect(body.session.data.token).toBe(token);
  });

  it("keeps loaded session data prototype-free", async () => {
    t.app.post("/proto", async (event) => {
      const session = await getSession(event, sessionConfig);
      await updateSession(event, sessionConfig, (await readBody(event)) as any);
      return {
        isAdmin: (session.data as any).isAdmin ?? null,
        inheritsObject: Object.prototype.isPrototypeOf(session.data),
      };
    });
    const seed = await t.fetch("/");
    const seedCookie = seed.headers.getSetCookie()[0].split(";")[0];
    const res = await t.fetch("/proto", {
      method: "POST",
      headers: { Cookie: seedCookie },
      body: '{"__proto__":{"isAdmin":true}}',
    });
    expect(await res.json()).toEqual({ isAdmin: null, inheritsObject: false });
  });

  describe("lazy creation", () => {
    const lazyConfig: SessionConfig = {
      name: "h3-lazy",
      password: "1234567123456712345671234567123456712345671234567",
    };

    it("does not persist a session that is only read", async () => {
      t.app.get("/peek", async (event) => {
        const session = await getSession(event, lazyConfig);
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/peek");
      expect(res.headers.getSetCookie()).toHaveLength(0);
      expect(await res.json()).toMatchObject({ data: {} });
    });

    it("persists on the first write after a read", async () => {
      t.app.get("/login", async (event) => {
        await getSession(event, lazyConfig);
        const session = await updateSession(event, lazyConfig, { user: "alice" });
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/login");
      expect(res.headers.getSetCookie()).toHaveLength(1);
      expect(res.headers.getSetCookie()[0]).toContain("h3-lazy=");
      expect(await res.json()).toMatchObject({ data: { user: "alice" } });
    });

    it("seals once when updateSession creates the session", async () => {
      const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
      t.app.get("/seal-count", async (event) => {
        await updateSession(event, lazyConfig, { user: "alice" });
        return "ok";
      });

      deriveBits.mockClear();
      const res = await t.fetch("/seal-count");
      expect(res.headers.getSetCookie()).toHaveLength(1);
      // Two derivations (encryption + integrity) for a single seal
      expect(deriveBits).toHaveBeenCalledTimes(2);
      deriveBits.mockRestore();
    });

    it("useSession still force-inits after a bare getSession", async () => {
      t.app.get("/peek-then-use", async (event) => {
        await getSession(event, lazyConfig); // e.g. auth middleware peeking
        const session = await useSession(event, lazyConfig);
        return { id: session.id };
      });

      const res = await t.fetch("/peek-then-use");
      expect(res.headers.getSetCookie()).toHaveLength(1);
    });

    it("useSession still force-inits when read concurrently", async () => {
      t.app.get("/concurrent", async (event) => {
        const [, session] = await Promise.all([
          getSession(event, lazyConfig),
          useSession(event, lazyConfig),
        ]);
        return { id: session.id };
      });

      const res = await t.fetch("/concurrent");
      expect(res.headers.getSetCookie()).toHaveLength(1);
    });

    it("keeps the session id stable across requests once persisted", async () => {
      t.app.get("/stable", async (event) => {
        const session = await useSession(event, lazyConfig);
        return { id: session.id };
      });

      const res1 = await t.fetch("/stable");
      const setCookie = res1.headers.getSetCookie()[0];
      const { id } = await res1.json();

      const res2 = await t.fetch("/stable", {
        headers: { Cookie: setCookie.split(";")[0] },
      });
      expect(await res2.json()).toMatchObject({ id });
    });
  });

  describe("password rotation", () => {
    const NEW = "rotation-new-password-0123456789ab";
    const OLD = "rotation-old-password-0123456789ab";
    const OTHER = "rotation-other-password-0123456789";
    const UNKNOWN = "rotation-unknown-password-0123456789";

    let rotationConfig: SessionConfig;

    const sealedWith = (password: string, options = sealDefaults) =>
      seal({ id: "old-session", createdAt: Date.now(), data: { user: "alice" } }, password, options);

    const legacyOptions = {
      ...sealDefaults,
      encryption: { ...sealDefaults.encryption, iterations: 1 },
      integrity: { ...sealDefaults.integrity, iterations: 1 },
    };

    beforeEach(() => {
      rotationConfig = {
        name: "h3-rotate",
        password: NEW,
        generateId: () => "rotated-session",
      };
      t.app.get("/rotate", async (event) => {
        const session = await useSession(event, rotationConfig);
        return { id: session.id, data: session.data };
      });
      t.app.get("/rotate-unseal", async (event) => {
        const sealed = await sealedWith(NEW);
        try {
          await unsealSession(event, { ...rotationConfig, extraUnsealPasswords: ["curta"] }, sealed);
          return { error: null };
        } catch (error) {
          return { error: (error as Error).message };
        }
      });
      t.app.get("/rotate-open", async (event) => {
        try {
          const sealed = event.req.headers.get("x-sealed")!;
          const unsealed = await unsealSession(event, rotationConfig, sealed);
          return { id: unsealed.id };
        } catch (error) {
          return { error: (error as Error).message };
        }
      });
      t.app.get("/rotate-write", async (event) => {
        await updateSession(event, rotationConfig, { user: "alice" });
        return "ok";
      });
    });

    it("accepts a session sealed with a previous password", async () => {
      rotationConfig.extraUnsealPasswords = [OLD];
      const res = await t.fetch("/rotate", {
        headers: { Cookie: `h3-rotate=${await sealedWith(OLD)}` },
      });
      expect(await res.json()).toMatchObject({
        id: "old-session",
        data: { user: "alice" },
      });
    });

    it("rejects a session sealed with an unknown password", async () => {
      rotationConfig.extraUnsealPasswords = [OLD];
      const res = await t.fetch("/rotate", {
        headers: { Cookie: `h3-rotate=${await sealedWith(UNKNOWN)}` },
      });
      const body = await res.json();
      expect(body.id).not.toBe("old-session");
      expect(body.data).toEqual({});
    });

    it("seals new sessions only with the current password", async () => {
      rotationConfig.extraUnsealPasswords = [OLD];
      const res = await t.fetch("/rotate-write");
      const cookie = decodeURIComponent(
        res.headers.getSetCookie()[0].match(/h3-rotate=([^;]+)/)![1],
      );
      await expect(unseal(cookie, OLD, sealDefaults)).rejects.toThrow("Bad hmac value");
      expect(await unseal(cookie, NEW, sealDefaults)).toMatchObject({
        data: { user: "alice" },
      });
    });

    it("rejects previous passwords when the extra list is empty", async () => {
      rotationConfig.extraUnsealPasswords = [];
      const res = await t.fetch("/rotate", {
        headers: { Cookie: `h3-rotate=${await sealedWith(OLD)}` },
      });
      const body = await res.json();
      expect(body.id).not.toBe("old-session");
      expect(body.data).toEqual({});
    });

    it("rejects previous passwords when the extra list is absent", async () => {
      const res = await t.fetch("/rotate", {
        headers: { Cookie: `h3-rotate=${await sealedWith(OLD)}` },
      });
      const body = await res.json();
      expect(body.id).not.toBe("old-session");
      expect(body.data).toEqual({});
    });

    it("rejects a short extra password", async () => {
      rotationConfig.extraUnsealPasswords = ["curta"];
      const res = await t.fetch("/rotate-unseal");
      expect(await res.json()).toEqual({
        error: "Password string too short (min 32 characters required)",
      });
    });

    it("tries passwords in order and stops at the first match", async () => {
      rotationConfig.extraUnsealPasswords = [OTHER, OLD];
      const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
      const cookie = `h3-rotate=${await sealedWith(OLD)}`;

      deriveBits.mockClear();
      const res = await t.fetch("/rotate", { headers: { Cookie: cookie } });
      expect(await res.json()).toMatchObject({ id: "old-session" });
      // One failed integrity derivation with NEW, then encryption + integrity with OLD.
      // OTHER is never tried, so a fourth call would mean it was.
      expect(deriveBits).toHaveBeenCalledTimes(3);
      deriveBits.mockRestore();
    });

    it("does not try other passwords for an expired session", async () => {
      rotationConfig.extraUnsealPasswords = [OTHER, OLD];
      const t0 = Date.parse("2030-01-01T00:00:00Z");
      vi.useFakeTimers({ toFake: ["Date"], now: t0 });
      try {
        const sealed = await seal(
          { id: "old-session", createdAt: t0, data: { user: "alice" } },
          OLD,
          { ...sealDefaults, ttl: 1000 },
        );
        vi.setSystemTime(t0 + 24 * 60 * 60 * 1000);

        const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
        const res = await t.fetch("/rotate", {
          headers: { Cookie: `h3-rotate=${sealed}` },
        });
        const body = await res.json();
        expect(body.id).not.toBe("old-session");
        expect(body.data).toEqual({});
        expect(deriveBits).toHaveBeenCalledTimes(0);
        deriveBits.mockRestore();
      } finally {
        vi.useRealTimers();
      }
    });

    it("unseals legacy sessions sealed with a previous password", async () => {
      rotationConfig.extraUnsealPasswords = [OLD];
      const res = await t.fetch("/rotate", {
        headers: { Cookie: `h3-rotate=${await sealedWith(OLD, legacyOptions)}` },
      });
      expect(await res.json()).toMatchObject({
        id: "old-session",
        data: { user: "alice" },
      });

      // Legacy cookie is resealed with the current password and default iterations
      const setCookies = res.headers.getSetCookie();
      expect(setCookies).toHaveLength(1);
      const resealed = decodeURIComponent(setCookies[0].match(/h3-rotate=([^;]+)/)![1]);
      expect(await unseal(resealed, NEW, sealDefaults)).toMatchObject({
        id: "old-session",
      });
    });

    it("rejects legacy sessions from a previous password with legacySealFallback: false", async () => {
      rotationConfig.extraUnsealPasswords = [OLD];
      rotationConfig.legacySealFallback = false;
      const res = await t.fetch("/rotate", {
        headers: { Cookie: `h3-rotate=${await sealedWith(OLD, legacyOptions)}` },
      });
      const body = await res.json();
      expect(body.id).not.toBe("old-session");
      expect(body.data).toEqual({});
    });
  });
});

