        );
        vi.setSystemTime(t0 + 24 * 60 * 60 * 1000);

        const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
        const res = await t.fetch("/rotate", {
          headers: { Cookie: `h3-rotate=${sealed}` },
